package dev.veltraph.client.greenhouse;

import java.util.*;
import net.minecraft.core.component.*;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.chat.Component;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.ItemLore;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;

/** Actual ItemStack/effective-component codecs, not fabricated identity strings. */
class GreenhouseNativeInventoryTest {
    @BeforeAll static void registry(){GreenhouseDiagnosticAssociationTest.nativeRegistry();}
    @Test void nativeSlotMovesWithEqualAggregateCountsChangeIntegrity(){var before=GreenhouseDiagnosticAssociationTest.nativeInventory();var cells=GreenhouseDiagnosticAssociationTest.items();var diamond=cells.get(11);cells.set(11,ItemStack.EMPTY);cells.set(12,diamond);var moved=GreenhouseNativeInventory.capture(cells,GreenhouseDiagnosticAssociationTest.gear(),ItemStack.EMPTY,3,GreenhouseDiagnosticAssociationTest.registry);assertNotEquals(before,moved);assertFalse(before.sameSlotsAndCursor(moved));assertEquals(7,moved.inventorySlot(12).nativeCount());}
    @Test void actualEffectiveNameLoreDamageDefaultAndCountMutationsFail(){for(int n=0;n<5;n++){var cells=GreenhouseDiagnosticAssociationTest.items();if(n==2)cells.set(3,new ItemStack(Items.IRON_AXE));var before=GreenhouseNativeInventory.capture(cells,GreenhouseDiagnosticAssociationTest.gear(),ItemStack.EMPTY,3,GreenhouseDiagnosticAssociationTest.registry);var tool=cells.get(3);switch(n){case 0->tool.set(DataComponents.CUSTOM_NAME,Component.literal("changed"));case 1->tool.set(DataComponents.LORE,new ItemLore(List.of(Component.literal("changed"))));case 2->tool.setDamageValue(7);case 3->tool.set(DataComponents.MAX_STACK_SIZE,16);case 4->tool.setCount(2);}var changed=GreenhouseNativeInventory.capture(cells,GreenhouseDiagnosticAssociationTest.gear(),ItemStack.EMPTY,3,GreenhouseDiagnosticAssociationTest.registry);assertNotEquals(before,changed);assertNotEquals(before.tool().identity(),changed.tool().identity());}}
    @Test void cursorAndSelectedNativeSlotAreIndependentExactFacts(){var before=GreenhouseDiagnosticAssociationTest.nativeInventory();var cursor=GreenhouseNativeInventory.capture(GreenhouseDiagnosticAssociationTest.items(),GreenhouseDiagnosticAssociationTest.gear(),new ItemStack(Items.DIAMOND,1),3,GreenhouseDiagnosticAssociationTest.registry);assertNotEquals(before,cursor);assertFalse(cursor.cursorEmpty());var selected=GreenhouseNativeInventory.capture(GreenhouseDiagnosticAssociationTest.items(),GreenhouseDiagnosticAssociationTest.gear(),ItemStack.EMPTY,4,GreenhouseDiagnosticAssociationTest.registry);assertNotEquals(before,selected);assertTrue(before.sameSlotsAndCursor(selected));}
    @Test void unsupportedTransientComponentIsRejectedBeforeAuthority(){var cells=GreenhouseDiagnosticAssociationTest.items();var transientType=DataComponentType.<String>builder().networkSynchronized(ByteBufCodecs.STRING_UTF8).build();cells.get(3).set(transientType,"not-persistable");assertThrows(IllegalArgumentException.class,()->GreenhouseNativeInventory.capture(cells,GreenhouseDiagnosticAssociationTest.gear(),ItemStack.EMPTY,3,GreenhouseDiagnosticAssociationTest.registry));}
    @Test void exactResourceTemplateAllowsOnlyItsDeclaredNativeSlot(){var cells=GreenhouseDiagnosticAssociationTest.items();cells.set(10,new ItemStack(Items.GLASS_BOTTLE,3));var before=GreenhouseNativeInventory.capture(cells,GreenhouseDiagnosticAssociationTest.gear(),ItemStack.EMPTY,3,GreenhouseDiagnosticAssociationTest.registry);var exactAfter=cells.get(10).copy();exactAfter.shrink(1);var after=before.replacingResource(10,exactAfter,GreenhouseDiagnosticAssociationTest.registry);cells.set(10,exactAfter);assertTrue(after.sameSlotsAndCursor(GreenhouseNativeInventory.capture(cells,GreenhouseDiagnosticAssociationTest.gear(),ItemStack.EMPTY,3,GreenhouseDiagnosticAssociationTest.registry)));cells.set(10,ItemStack.EMPTY);cells.set(12,exactAfter);assertFalse(after.sameSlotsAndCursor(GreenhouseNativeInventory.capture(cells,GreenhouseDiagnosticAssociationTest.gear(),ItemStack.EMPTY,3,GreenhouseDiagnosticAssociationTest.registry)));}
    @Test void nativeEquipmentMutationsCannotHideOutsideInventorySlots(){var before=GreenhouseDiagnosticAssociationTest.nativeInventory();var gear=GreenhouseDiagnosticAssociationTest.gear();gear.put(net.minecraft.world.entity.EquipmentSlot.OFFHAND,new ItemStack(Items.SHIELD));var changed=GreenhouseNativeInventory.capture(GreenhouseDiagnosticAssociationTest.items(),gear,ItemStack.EMPTY,3,GreenhouseDiagnosticAssociationTest.registry);assertFalse(before.sameSlotsAndCursor(changed));}

}
